async function promotion(){try{const d=await api('/.netlify/functions/social-promotions');const types=[['viral_profile','Viral Profile'],['viral_video','Viral Video'],['photo','Photo Promotion'],['relationship','Relationship Promotion'],['business','Business Promotion'],['music','Music Promotion'],['follower_growth','Follower Growth']];const rows=(d.promotions||[]).map(p=>'<article class="aam-social-card"><div class="aam-social-muted">MANAGER PROMOTION · '+esc(p.status.replaceAll('_',' '))+'</div><h3>'+esc(p.title)+'</h3><img class="aam-social-preview" src="'+esc(p.media_url)+'" alt="Advert picture"><p>'+esc(p.description)+'</p><p class="aam-social-muted">'+esc((types.find(x=>x[0]===p.promotion_type)||[])[1]||p.promotion_type)+' · '+Number(p.requested_days)+' days</p>'+(p.price_coins?'<p>Price: <strong>'+Number(p.price_coins).toLocaleString()+' Money Coins</strong></p>':'<p class="aam-social-muted">Price pending review.</p>')+(p.status==='awaiting_payment'&&p.provider_status==='ready'?'<button class="aam-social-btn" onclick="AAMSocial.payPromotion(\''+p.id+'\')">Pay with Money Coins</button>':'')+(p.admin_note?'<p>'+esc(p.admin_note)+'</p>':'')+'<p class="aam-social-muted">Provider: '+esc(p.provider_status.replaceAll('_',' '))+'</p></article>').join('');mount('<div class="aam-social-card"><button class="aam-social-btn secondary" onclick="AAMSocial.open(\'profile\')">← Profile</button><h2>Manager Promotion</h2><p>Prepare an advert for your profile, picture, video, relationship, business or music.</p><div class="aam-social-balance">'+Number(d.promotion_balance||0).toLocaleString()+' Money Coins</div><p class="aam-social-muted">Promotion Balance is your purchased Money Coins. Free Coins are not accepted. Your advert is reviewed before pricing. No coins are deducted on submission.</p><label>Promotion type</label><select class="aam-social-field" id="aamPromoType">'+types.map(x=>'<option value="'+x[0]+'">'+x[1]+'</option>').join('')+'</select><label>Advert title</label><input class="aam-social-field" id="aamPromoTitle" maxlength="100" placeholder="Advert title"><label>Description</label><textarea class="aam-social-field" id="aamPromoDescription" maxlength="2000" placeholder="Describe your advert"></textarea><label>Advert picture</label><input class="aam-social-field" id="aamPromoImage" type="file" accept="image/jpeg,image/png,image/webp"><label>Profile or destination link (optional)</label><input class="aam-social-field" id="aamPromoDestination" maxlength="500" placeholder="Your profile or destination link"><label>Requested duration</label><select class="aam-social-field" id="aamPromoDays"><option value="1">1 day</option><option value="3">3 days</option><option value="7" selected>7 days</option><option value="14">14 days</option><option value="30">30 days</option></select><button class="aam-social-btn" onclick="AAMSocial.submitPromotion()">Submit advert for review</button><p class="aam-social-muted">Campaigns will not run until the advertising provider is connected and approval is complete.</p></div><h3>Your promotions</h3>'+(rows||'<div class="aam-social-card aam-social-muted">No promotions submitted yet.</div>'),'profile');}catch(e){notice(e.message);}}
async function submitPromotion(){const file=document.getElementById('aamPromoImage')?.files?.[0];if(!file)return notice('Choose your advert picture.');const title=document.getElementById('aamPromoTitle')?.value||'',description=document.getElementById('aamPromoDescription')?.value||'';if(title.trim().length<3||description.trim().length<5)return notice('Enter an advert title and description.');try{const signed=await api('/.netlify/functions/social-promotions','POST',{action:'sign_upload',mime_type:file.type});const uploaded=await socialDb.storage.from('aam-social-media').uploadToSignedUrl(signed.path,signed.token,file,{contentType:file.type,upsert:false});if(uploaded.error)throw uploaded.error;const d=await api('/.netlify/functions/social-promotions','POST',{action:'create',promotion_type:document.getElementById('aamPromoType').value,title,description,media_path:signed.path,destination_url:document.getElementById('aamPromoDestination').value||'',requested_days:Number(document.getElementById('aamPromoDays').value||7)});notice(d.message||'Advert submitted for review.');promotion();}catch(e){notice(e.message||'Could not submit advert.');}}
async function payPromotion(id){if(!confirm('Pay the approved advert price using Money Coins? Free Coins cannot be used.'))return;try{const d=await api('/.netlify/functions/social-promotions','POST',{action:'pay',promotion_id:id});notice(d.message||'Payment recorded.');promotion();}catch(e){notice(e.message);}}
function dock(active='home'){if(!customer()||!token()||!root()||!document.querySelector('.container'))return;let n=document.getElementById('aamSocialDock');if(!n){n=document.createElement('nav');n.id='aamSocialDock';n.setAttribute('aria-label','Social navigation');document.body.appendChild(n);}n.innerHTML=[['home','⌂','Home'],['upload','＋','Post'],['chat','▤','Chat'],['profile','◉','Profile']].map(([id,icon,label])=>'<button class="'+(active===id?'active':'')+'" onclick="AAMSocial.open(\''+id+'\')"><div style="font-size:19px">'+icon+'</div>'+label+'</button>').join('');}
function mount(html,active){const a=root();if(!a)return;a.innerHTML='<header class="topbar"><div class="brand">All Ads Manager</div><div class="aam-top-actions">'+(adminToken()?'':'<button class="aam-notify-btn" id="aamNotifyBtn" onclick="AAMSocial.notifications()">♢</button>')+'<button class="tiny-admin" onclick="AAMSocial.open(\'dashboard\')">⋯</button></div></header><main class="container" id="aamSocialRoot"><div class="aam-social-wrap">'+html+'</div></main>';dock(active);updateNotificationBadge();}
function coinPackagesMarkup(){const amounts=[500,1000,2000,5000,10000,20000,50000];return '<details class="aam-social-card"><summary><strong>Buy Money Coins</strong></summary><p class="aam-social-muted">1 coin = ₦1. Minimum purchase ₦500. Money Coins and Free Coins are kept separately. Free Coins are only for watching paid videos. Money Coins can unlock videos, pay for Manager Promotion, and add pictures during video calls. Your tools wallet is separate.</p><label>Email for this Paystack payment only</label><input class="aam-social-field" id="aamCoinEmail" type="email" autocomplete="email" placeholder="Receipt email"><p class="aam-social-muted">This is only for your payment receipt. It is not required for your All Ads Manager account.</p><label>Payment method</label><select class="aam-social-field" id="aamCoinMethod"><option value="bank_transfer">Bank Transfer</option><option value="card">ATM / Card</option></select><div class="aam-coin-packages">'+amounts.map(n=>'<button class="aam-social-btn secondary" type="button" onclick="AAMSocial.buyCoins('+n+')">₦'+n.toLocaleString()+' · '+n.toLocaleString()+' coins</button>').join('')+'</div></details>';}
async function buyCoins(amount){const email=document.getElementById('aamCoinEmail')?.value.trim()||'',method=document.getElementById('aamCoinMethod')?.value||'bank_transfer';if(!email)return notice('Enter your email for the Paystack receipt.');try{const r=await fetch('/.netlify/functions/social-coin-create',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:token(),amount,email,method})});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Could not start coin purchase.');if(!d.authorization_url)throw new Error('Paystack did not return a payment link.');window.location.href=d.authorization_url;}catch(e){notice(e.message||'Could not start coin purchase.');}}
async function home(){if(!customer())return;try{const d=await api('/.netlify/functions/social-core');notificationSoundChoice=Number(d.preferences?.notification_sound||1);if(!d.profile?.adult_confirmed_at){mount('<div class="aam-social-card"><h2>Adults only · 18+</h2><p>This social community is for adults aged 18 or older.</p><p>By continuing, you confirm that you are at least 18 years old.</p><button class="aam-social-btn" onclick="AAMSocial.confirmAdult()">I confirm I am 18 or older</button></div>','home');return;}const f=await api('/.netlify/functions/social-feed');mount('<div class="aam-social-card"><div class="aam-social-muted">YOUR COIN BALANCE</div><div class="aam-social-balance">'+Number(d.coin_balance||0).toLocaleString()+' total coins</div><p>Free Coins: <strong>'+Number(d.free_coin_balance||0).toLocaleString()+'</strong></p><p>Money Coins: <strong>'+Number(d.purchased_coin_balance||0).toLocaleString()+'</strong></p><p>Promotion Balance: <strong>'+Number(d.money_coin_balance||0).toLocaleString()+' Money Coins</strong></p><button class="aam-social-btn" onclick="AAMSocial.openPromotion()">Manager Promotion</button><div class="aam-social-muted">Pictures, API-sourced videos and friends’ uploaded videos are free to view. Only videos marked as paid cost 1 coin (₦1) to unlock. Free Coins cannot be used for promotions or call picture additions; only Money Coins spent on paid videos count as cash earnings.</div></div>'+coinPackagesMarkup()+'<div class="aam-social-card"><h3>Find friends</h3><input class="aam-social-field" id="aamDiscoverQuery" maxlength="40" placeholder="Search by display name"><button class="aam-social-btn" onclick="AAMSocial.discover()">Search</button><div id="aamDiscoverResults"></div></div><h2>Home</h2><div id="aamSocialPosts">'+(f.posts||[]).map(postCard).join('')+'</div>','home');}catch(e){mount('<div class="aam-social-card"><h2>Home feed</h2><p>'+esc(e.message)+'</p><button class="aam-social-btn" onclick="AAMSocial.open(\'dashboard\')">Back to Dashboard</button></div>','home');}}
function postCard(p){const locked=!!p.locked_video;const follow=p.creator?.id?'<div class="aam-social-creator-actions">'+(p.is_following?'<span class="aam-social-muted">Following</span>':'<button class="aam-social-btn secondary" onclick="AAMSocial.follow(&quot;'+esc(p.creator.id)+'&quot;)">Follow</button>')+'<button class="aam-social-btn secondary" onclick="AAMSocial.startChat(&quot;'+esc(p.creator.id)+'&quot;)">Message</button></div>':'';const media=locked?'<div class="aam-social-locked">'+(p.thumbnail_url?'<img class="aam-social-thumbnail" src="'+esc(p.thumbnail_url)+'" alt="Locked video preview">':'')+'<div><strong>🔒 Paid video</strong><p>Watch this video for 1 coin (₦1).</p><button class="aam-social-btn" onclick="AAMSocial.unlockVideo(&quot;'+esc(p.id)+'&quot;)">Watch for 1 coin (₦1)</button></div></div>':(p.media_type==='video'?'<video class="aam-social-media" controls playsinline preload="none" src="'+esc(p.media_url||'')+'"></video>':'<img class="aam-social-media" loading="lazy" src="'+esc(p.media_url||'')+'" alt="Post image">');return '<article class="aam-social-card"><div class="aam-social-creator">'+(p.creator?.avatar_url?'<img class="aam-social-feed-avatar" src="'+esc(p.creator.avatar_url)+'" alt="">':'')+'<strong>'+esc(p.creator?.name||'Friend')+(p.verified?'<span class="aam-verified" aria-label="Verified">✓</span>':'')+'</strong>'+(p.creator?.id?'':'<button class="aam-social-btn secondary" onclick="AAMSocial.viewAdminProfile()">View friend</button>')+(p.follower_count!=null?'<span class="aam-social-muted">'+formatCount(p.follower_count)+' followers · 0 following</span>':'')+follow+'</div><div class="aam-social-muted">'+new Date(p.created_at).toLocaleString()+'</div>'+media+(p.caption?'<p>'+esc(p.caption)+'</p>':'')+'<div class="aam-social-actions"><button class="aam-social-btn secondary" onclick="AAMSocial.like(&quot;'+esc(p.id)+'&quot;)">'+(p.liked?'♥ Liked':'♡ Like')+' · '+formatCount(p.like_count||0)+'</button>'+(p.comments_enabled?'<button class="aam-social-btn secondary" onclick="AAMSocial.comments(&quot;'+esc(p.id)+'&quot;)">Comments · '+formatCount(p.comment_count||0)+'</button>':'')+'<button class="aam-social-btn secondary" onclick="AAMSocial.sharePost(&quot;'+esc(p.id)+'&quot;)">Share in chat</button><button class="aam-social-btn secondary" onclick="AAMSocial.sharePostLink(&quot;'+esc(p.id)+'&quot;)">Share link</button></div><div id="aamComments-'+esc(p.id)+'"></div></article>';}
