async function discover(){const q=document.getElementById('aamDiscoverQuery')?.value.trim()||'',box=document.getElementById('aamDiscoverResults');if(q.length<2)return notice('Enter at least two letters.');try{const d=await api('/.netlify/functions/social-discover?q='+encodeURIComponent(q));box.innerHTML=(d.profiles||[]).map(p=>'<div class="aam-social-discover-row">'+(p.avatar_url?'<img class="aam-social-feed-avatar" src="'+esc(p.avatar_url)+'" alt="">':'')+'<strong>'+esc(p.display_name||'Friend')+'</strong><p>'+esc(p.bio||'')+'</p><button class="aam-social-btn secondary" onclick="AAMSocial.viewProfile(&quot;'+esc(p.customer_id)+'&quot;)">View profile</button></div>').join('')||'<p class="aam-social-muted">No friends found.</p>';}catch(e){notice(e.message);}}
async function viewAdminProfile(){try{const d=await api('/.netlify/functions/social-discover?admin_profile=1'),p=d.profile||{};mount('<div class="aam-social-card"><button class="aam-social-btn secondary" onclick="AAMSocial.open(&quot;home&quot;)">← Home</button>'+(p.avatar_url?'<img class="aam-social-avatar" src="'+esc(p.avatar_url)+'" alt="">':'')+'<h2>'+esc(p.display_name||'All Ads Manager')+'<span class="aam-verified" aria-label="Verified">✓</span></h2><p class="aam-social-muted">'+formatCount(d.followers||0)+' followers · '+formatCount(d.likes||0)+' likes on recent posts · 0 following · '+formatCount(d.profile_views||0)+' views</p></div>'+(d.posts||[]).map(postCard).join(''),'home');}catch(e){notice(e.message);}}
