function upload(){mount('<div class="aam-social-card"><h2>Create a post</h2><p class="aam-social-muted">Posting is free. Pictures, API-sourced videos and your own uploaded videos are free to view. Only videos marked as paid cost 1 coin (₦1) per view.</p><input class="aam-social-field" id="aamMedia" type="file" accept="image/jpeg,image/png,image/webp,video/mp4,video/quicktime,video/webm"><textarea class="aam-social-field" id="aamCaption" maxlength="2200" placeholder="Write a caption…"></textarea><div id="aamUploadStatus" class="aam-social-muted"></div><button class="aam-social-btn" onclick="AAMSocial.publish()">Publish</button></div>','upload');}
async function captureVideoThumbnail(file){return new Promise(resolve=>{const video=document.createElement('video'),url=URL.createObjectURL(file),canvas=document.createElement('canvas');let done=false;const finish=value=>{if(done)return;done=true;URL.revokeObjectURL(url);resolve(value);};video.muted=true;video.playsInline=true;video.preload='metadata';video.onloadedmetadata=()=>{try{video.currentTime=Math.min(.5,Math.max(0,(video.duration||1)/3));}catch(e){finish(null);}};video.onseeked=()=>{try{canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d').drawImage(video,0,0,canvas.width,canvas.height);canvas.toBlob(blob=>finish(blob),'image/jpeg',.78);}catch(e){finish(null);}};video.onerror=()=>finish(null);video.src=url;setTimeout(()=>finish(null),8000);});}
async function publish(){const file=document.getElementById('aamMedia')?.files?.[0];if(!file)return notice('Choose a picture or video first.');const status=document.getElementById('aamUploadStatus');try{if(status)status.textContent='Preparing upload…';const signed=await api('/.netlify/functions/social-feed','POST',{action:'sign_upload',mime_type:file.type});const {data,error}=await socialDb.storage.from('aam-social-media').uploadToSignedUrl(signed.path,signed.token,file,{contentType:file.type,upsert:false});if(error)throw error;let thumbnailPath=null;if(file.type.startsWith('video/')){const thumb=await captureVideoThumbnail(file);if(thumb){const st=await api('/.netlify/functions/social-feed','POST',{action:'sign_thumbnail_upload'}),tu=await socialDb.storage.from('aam-social-media').uploadToSignedUrl(st.path,st.token,thumb,{contentType:'image/jpeg',upsert:false});if(tu.error)throw tu.error;thumbnailPath=st.path;}}if(status)status.textContent='Publishing…';await api('/.netlify/functions/social-feed','POST',{action:'publish_post',media_path:signed.path,thumbnail_path:thumbnailPath,mime_type:file.type,caption:document.getElementById('aamCaption')?.value||''});notice('Your post has been published.');home();}catch(e){if(status)status.textContent=e.message;else notice(e.message);}}
async function profile(){try{const d=await api('/.netlify/functions/social-core');const p=d.profile||{},prefs=d.preferences||{};notificationSoundChoice=Number(prefs.notification_sound||1);const sounds=Array.from({length:15},(_,i)=>'<option value="'+(i+1)+'"'+(Number(prefs.notification_sound||1)===i+1?' selected':'')+'>Calm sound '+(i+1)+'</option>').join('');const wallpapers=['default',...Array.from({length:20},(_,i)=>'theme-'+String(i+1).padStart(2,'0')),'custom',...(prefs.custom_wallpaper_path?[]:[])].map((v)=>'<option value="'+v+'"'+((prefs.chat_wallpaper||'default')===v?' selected':'')+'>'+(v==='default'?'Default':'Wallpaper '+v.slice(-2))+'</option>').join('');mount('<div class="aam-social-card"><h2>My Profile</h2>'+(p.avatar_url?'<img class="aam-social-avatar" src="'+esc(p.avatar_url)+'" alt="Profile picture">':'')+'<label>Profile picture</label><input class="aam-social-field" id="aamAvatarFile" type="file" accept="image/jpeg,image/png,image/webp"><button class="aam-social-btn secondary" onclick="AAMSocial.updateAvatar()">Update picture</button><div class="aam-social-balance">'+Number(d.coin_balance||0).toLocaleString()+' total coins</div><p>Free coins: <strong>'+Number(d.free_coin_balance||0).toLocaleString()+'</strong> · Money Coins: <strong>'+Number(d.purchased_coin_balance||0).toLocaleString()+'</strong></p><p class="aam-social-muted">'+formatCount(d.followers||0)+' followers · '+formatCount(d.following||0)+' following · '+formatCount(d.profile_views||0)+' views</p><p class="aam-social-muted">Referral number: '+esc(p.referral_code||'Preparing…')+'</p><input type="hidden" id="aamReferralCode" value="'+esc(p.referral_code||'')+'"><input type="hidden" id="aamReferralUrl" value="'+esc(window.location.origin+'/?referral='+(p.referral_code||''))+'"><div class="aam-social-actions"><button class="aam-social-btn secondary" onclick="AAMSocial.copyReferralCode()">Copy Referral Number</button><button class="aam-social-btn secondary" onclick="AAMSocial.copyReferralLink()">Copy Referral Link</button></div><p class="aam-social-muted">Profile ID: '+esc(p.customer_id||'')+'</p><input type="hidden" id="aamProfileId" value="'+esc(p.customer_id||'')+'"><input type="hidden" id="aamProfileUrl" value="'+esc(window.location.origin+'/?creator='+(p.customer_id||''))+'"><div class="aam-social-actions"><button class="aam-social-btn secondary" onclick="AAMSocial.copyProfileId()">Copy Profile ID</button><button class="aam-social-btn secondary" onclick="AAMSocial.copyProfileLink()">Copy Profile Link</button><button class="aam-social-btn secondary" onclick="AAMSocial.shareProfile()">Share Profile</button></div><label>Display name</label><input class="aam-social-field" id="aamDisplayName" maxlength="40" value="'+esc(p.display_name||'')+'"><label>Bio</label><textarea class="aam-social-field" id="aamBio" maxlength="300">'+esc(p.bio||'')+'</textarea><label class="aam-social-check"><input type="checkbox" id="aamPrivateProfile"'+(p.is_private?' checked':'')+'> Private profile</label><label class="aam-social-check"><input type="checkbox" id="aamCommentsEnabled"'+(p.comments_enabled===false?'':' checked')+'> Allow comments on my posts</label><button class="aam-social-btn" onclick="AAMSocial.saveProfile()">Save profile</button></div><div class="aam-social-card"><h3>Notification and chat settings</h3><label>Notification sound</label><select class="aam-social-field" id="aamSoundChoice">'+sounds+'</select><button class="aam-social-btn secondary" onclick="AAMSocial.previewSound()">Preview sound</button><label>Chat wallpaper</label><select class="aam-social-field" id="aamWallpaperChoice">'+wallpapers+'</select><input type="hidden" id="aamExistingWallpaperPath" value="'+esc(prefs.custom_wallpaper_path||'')+'"><label>Upload a custom wallpaper</label><input class="aam-social-field" type="file" id="aamCustomWallpaper" accept="image/jpeg,image/png,image/webp"><h4>Notification preferences</h4><label class="aam-social-check"><input type="checkbox" id="aamPrefViews"'+(prefs.profile_view_notifications===false?'':' checked')+'> Profile views</label><label class="aam-social-check"><input type="checkbox" id="aamPrefFollows"'+(prefs.follow_notifications===false?'':' checked')+'> New followers</label><label class="aam-social-check"><input type="checkbox" id="aamPrefLikes"'+(prefs.like_notifications===false?'':' checked')+'> Likes</label><label class="aam-social-check"><input type="checkbox" id="aamPrefComments"'+(prefs.comment_notifications===false?'':' checked')+'> Comments</label><label class="aam-social-check"><input type="checkbox" id="aamPrefShares"'+(prefs.share_notifications===false?'':' checked')+'> Shares</label><label class="aam-social-check"><input type="checkbox" id="aamPrefMessages"'+(prefs.message_notifications===false?'':' checked')+'> Messages</label><label class="aam-social-check"><input type="checkbox" id="aamPrefProfileUpdates"'+(prefs.profile_update_notifications===false?'':' checked')+'> Profile picture updates</label><button class="aam-social-btn" onclick="AAMSocial.savePreferences()">Save settings</button></div><div class="aam-social-card"><h3>All Ads Manager tools</h3><button class="aam-social-btn secondary" onclick="AAMSocial.open(\'dashboard\')">Open services dashboard</button></div>','profile');}catch(e){notice(e.message);}}
async function updateAvatar(){const file=document.getElementById('aamAvatarFile')?.files?.[0];if(!file)return notice('Choose a profile picture first.');try{const signed=await api('/.netlify/functions/social-feed','POST',{action:'sign_avatar_upload',mime_type:file.type}),up=await socialDb.storage.from('aam-social-media').uploadToSignedUrl(signed.path,signed.token,file,{contentType:file.type,upsert:false});if(up.error)throw up.error;await api('/.netlify/functions/social-core','POST',{action:'update_avatar',avatar_path:signed.path});notice('Profile picture updated. Your followers have been notified.');profile();}catch(e){notice(e.message);}}
async function saveProfile(){try{await api('/.netlify/functions/social-core','POST',{action:'update_profile',display_name:document.getElementById('aamDisplayName')?.value||'',bio:document.getElementById('aamBio')?.value||'',is_private:!!document.getElementById('aamPrivateProfile')?.checked,comments_enabled:!!document.getElementById('aamCommentsEnabled')?.checked});notice('Profile settings saved.');}catch(e){notice(e.message);}}
async function savePreferences(){try{let wallpaper=document.getElementById('aamWallpaperChoice')?.value||'default',path=wallpaper==='custom'?(document.getElementById('aamExistingWallpaperPath')?.value||''):null;const file=document.getElementById('aamCustomWallpaper')?.files?.[0];if(file){const signed=await api('/.netlify/functions/social-feed','POST',{action:'sign_wallpaper_upload',mime_type:file.type});const uploaded=await socialDb.storage.from('aam-social-media').uploadToSignedUrl(signed.path,signed.token,file,{contentType:file.type,upsert:false});if(uploaded.error)throw uploaded.error;path=signed.path;wallpaper='custom';}if(wallpaper==='custom'&&!path)throw new Error('Choose a wallpaper image first.');await api('/.netlify/functions/social-core','POST',{action:'update_preferences',notification_sound:Number(document.getElementById('aamSoundChoice')?.value||1),chat_wallpaper:wallpaper,custom_wallpaper_path:path});await api('/.netlify/functions/social-core','POST',{action:'update_notification_preferences',profile_view_notifications:!!document.getElementById('aamPrefViews')?.checked,follow_notifications:!!document.getElementById('aamPrefFollows')?.checked,like_notifications:!!document.getElementById('aamPrefLikes')?.checked,comment_notifications:!!document.getElementById('aamPrefComments')?.checked,share_notifications:!!document.getElementById('aamPrefShares')?.checked,message_notifications:!!document.getElementById('aamPrefMessages')?.checked,profile_update_notifications:!!document.getElementById('aamPrefProfileUpdates')?.checked});notice('Chat and notification settings saved.');}catch(e){notice(e.message);}}
function previewSound(){if(!window.AudioContext&&!window.webkitAudioContext)return notice('Sound preview is not supported on this device.');const id=Number(document.getElementById('aamSoundChoice')?.value||1),ctx=new (window.AudioContext||window.webkitAudioContext)(),notes=[440,494,523,587,659,392,349,330,294,262,698,784,880,988,1047],freq=notes[(id-1)%notes.length];[0,0.16].forEach((delay,i)=>{const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.value=freq*(i?1.25:1);g.gain.setValueAtTime(0.0001,ctx.currentTime+delay);g.gain.exponentialRampToValueAtTime(0.08,ctx.currentTime+delay+0.025);g.gain.exponentialRampToValueAtTime(0.0001,ctx.currentTime+delay+0.13);o.connect(g);g.connect(ctx.destination);o.start(ctx.currentTime+delay);o.stop(ctx.currentTime+delay+0.14);});setTimeout(()=>ctx.close(),600);}
function playNotificationSound(id){try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const ctx=new C(),notes=[440,494,523,587,659,392,349,330,294,262,698,784,880,988,1047],freq=notes[(Number(id||1)-1)%notes.length];[0,.17].forEach((delay,i)=>{const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.value=freq*(i?1.18:1);g.gain.setValueAtTime(.0001,ctx.currentTime+delay);g.gain.exponentialRampToValueAtTime(.035,ctx.currentTime+delay+.03);g.gain.exponentialRampToValueAtTime(.0001,ctx.currentTime+delay+.19);o.connect(g);g.connect(ctx.destination);o.start(ctx.currentTime+delay);o.stop(ctx.currentTime+delay+.2);});setTimeout(()=>ctx.close(),600);}catch(e){}}
async function updateNotificationBadge(){try{const d=await api('/.netlify/functions/social-notifications');if(lastUnreadCount!==null&&d.unread_count>lastUnreadCount&&!document.hidden)playNotificationSound(notificationSoundChoice);lastUnreadCount=Number(d.unread_count||0);const b=document.getElementById('aamNotifyBtn');if(b)b.innerHTML='♢'+(d.unread_count?'<span class="aam-notify-count">'+d.unread_count+'</span>':'');}catch(e){}}
async function notifications(){try{const d=await api('/.netlify/functions/social-notifications');mount('<div class="aam-social-card"><h2>Notifications</h2>'+(d.notifications||[]).map(n=>'<div class="aam-social-notification '+(n.read_at?'':'unread')+'">'+(n.actor?.avatar_url?'<img class="aam-notification-avatar" src="'+esc(n.actor.avatar_url)+'" alt="">':'')+'<strong>'+esc(n.actor?.display_name||'All Ads Manager')+'</strong><span>'+esc(n.title)+'</span><p>'+esc(n.body||'')+'</p><small>'+new Date(n.created_at).toLocaleString()+'</small></div>').join('')+(d.notifications?.length?'':'<p class="aam-social-muted">You have no notifications yet.</p>')+'</div>','profile');await api('/.netlify/functions/social-notifications','POST',{ids:(d.notifications||[]).map(n=>n.id)});updateNotificationBadge();}catch(e){notice(e.message);}}
async function chat(){if(window.aamChatRefreshTimer){clearInterval(window.aamChatRefreshTimer);window.aamChatRefreshTimer=null;window.aamActiveChatId=null;}try{const d=await api('/.netlify/functions/social-chat');mount('<div class="aam-social-card"><h2>Chats</h2><button class="aam-social-btn secondary" onclick="AAMSocial.messageAdmin()">Contact All Ads Manager</button>'+(d.conversations||[]).map(c=>'<button class="aam-social-chat-row" onclick="AAMSocial.openChat(&quot;'+esc(c.id)+'&quot;)"><strong>'+esc(c.other?.display_name||'Friend')+(c.other?.is_group?' · Community':'')+'</strong><small>'+(c.other?.is_group?formatCount(c.other.member_count)+' members · '+(c.other.group_role==='admin'?'Group admin':'Member'):(c.other?.last_seen_at&&Date.now()-new Date(c.other.last_seen_at).getTime()<120000?'Online':(c.other?.last_seen_at?'Last seen '+new Date(c.other.last_seen_at).toLocaleString():'Offline')))+'</small><span>'+(c.last_message?esc(c.last_message.body||'Media message'):'Start a conversation')+'</span></button>').join('')+'<p class="aam-social-muted">To start a chat, open a friend’s post and tap Message.</p></div>','chat');}catch(e){mount('<div class="aam-social-card"><h2>Chats</h2><p>'+esc(e.message)+'</p></div>','chat');}}
function messageAdmin(){if(window.aamChatPresenceTimer){clearInterval(window.aamChatPresenceTimer);window.aamChatPresenceTimer=null;}if(window.aamChatRefreshTimer){clearInterval(window.aamChatRefreshTimer);window.aamChatRefreshTimer=null;window.aamActiveChatId=null;}if(typeof window.supportPage==='function')window.supportPage();else notice('Administrator contact is not available right now.');}
async function startChat(id){try{const d=await api('/.netlify/functions/social-chat','POST',{action:'start',target_customer_id:id});openChat(d.conversation_id);}catch(e){notice(e.message);}}
function chatMessageHtml(m){return '<div class="aam-social-message '+(m.sender_id===customer()?'mine':'')+'" data-message-id="'+esc(m.id)+'"><strong>'+esc(m.creator?.display_name||'Friend')+'</strong><p>'+esc(m.body||((m.message_type==='voice')?'Voice note':'Media message'))+'</p><small>'+new Date(m.created_at).toLocaleString()+'</small>'+(m.sender_id===customer()?(m.read_by?.length?'<small class="aam-read">READ</small>':'<i class="aam-unread-dot"></i>'):'')+(m.message_type==='voice'&&m.media_url?'<audio controls preload="none" src="'+esc(m.media_url)+'"></audio>':m.message_type==='image'&&m.media_url?'<img class="aam-social-chat-media" loading="lazy" src="'+esc(m.media_url)+'" alt="Shared image">':m.message_type==='video'&&m.media_url?'<video class="aam-social-chat-media" controls playsinline preload="none" src="'+esc(m.media_url)+'"></video>':m.message_type==='shared_post'?'<button class="aam-social-btn secondary" onclick="AAMSocial.viewSharedPost(&quot;'+esc(m.shared_post_id||'')+'&quot;)">View shared post</button>':'')+'</div>';}
async function refreshChatMessages(id){try{if(window.aamActiveChatId!==id)return;const area=document.querySelector('.aam-social-chat-messages');if(!area)return;const nearBottom=area.scrollHeight-area.scrollTop-area.clientHeight<90;const d=await api('/.netlify/functions/social-chat?conversation_id='+encodeURIComponent(id));if(window.aamActiveChatId!==id)return;for(const m of (d.messages||[])){const existing=area.querySelector('[data-message-id="'+m.id+'"]');if(!existing){area.insertAdjacentHTML('beforeend',chatMessageHtml(m));continue;}if(m.sender_id===customer()&&m.read_by?.length&&!existing.querySelector('.aam-read')){const dot=existing.querySelector('.aam-unread-dot');if(dot)dot.outerHTML='<small class="aam-read">READ</small>';}}if(nearBottom)area.scrollTop=area.scrollHeight;}catch(e){}}
async function openChat(id){try{const [d,settings]=await Promise.all([api('/.netlify/functions/social-chat?conversation_id='+encodeURIComponent(id)),api('/.netlify/functions/social-core')]);const messages=d.messages||[];const wallpaper='wallpaper-'+(settings.preferences?.chat_wallpaper||'default');mount('<div class="aam-social-card"><button class="aam-social-btn secondary" onclick="AAMSocial.open(&quot;chat&quot;)">← Chats</button><h3>'+esc(d.conversation?.title||'Conversation')+'</h3><div class="aam-social-chat-messages '+wallpaper+'">'+messages.map(chatMessageHtml).join('')+'</div><textarea id="aamChatBody" class="aam-social-field" maxlength="5000" placeholder="Write a message…"></textarea><div class="aam-voice-controls"><button class="aam-social-btn secondary" onclick="AAMSocial.recordVoice(&quot;'+esc(id)+'&quot;)">🎙 Record voice note (max 60s)</button><span id="aamRecordingStatus" class="aam-social-muted"></span></div><label>Attach picture or video</label><input class="aam-social-field" id="aamChatMedia" type="file" accept="image/jpeg,image/png,image/webp,video/mp4,video/quicktime,video/webm"><button class="aam-social-btn secondary" onclick="AAMSocial.sendChatMedia(&quot;'+esc(id)+'&quot;)">Send attachment</button><button class="aam-social-btn" onclick="AAMSocial.sendChat(&quot;'+esc(id)+'&quot;)">Send</button></div>','chat');const chatArea=document.querySelector('.aam-social-chat-messages');if(chatArea)chatArea.scrollTop=chatArea.scrollHeight;if(chatArea&&settings.preferences?.custom_wallpaper_url){chatArea.style.backgroundImage='url("'+settings.preferences.custom_wallpaper_url+'")';chatArea.style.backgroundSize='cover';chatArea.style.backgroundPosition='center';}if(window.aamChatPresenceTimer)clearInterval(window.aamChatPresenceTimer);if(window.aamChatRefreshTimer)clearInterval(window.aamChatRefreshTimer);window.aamActiveChatId=id;const touch=()=>api('/.netlify/functions/social-chat','POST',{action:'touch',conversation_id:id}).catch(()=>{});touch();window.aamChatPresenceTimer=setInterval(touch,30000);window.aamChatRefreshTimer=setInterval(()=>refreshChatMessages(id),4000);}catch(e){notice(e.message);}}
async function recordVoice(id){if(window.aamVoiceRecorder?.state==='recording'){window.aamVoiceRecorder.stop();return;}try{if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw new Error('Voice recording is not supported in this browser.');const stream=await navigator.mediaDevices.getUserMedia({audio:true});const mime=MediaRecorder.isTypeSupported('audio/webm')?'audio/webm':(MediaRecorder.isTypeSupported('audio/mp4')?'audio/mp4':'');if(!mime)throw new Error('This browser cannot record a supported voice-note format.');const recorder=new MediaRecorder(stream,{mimeType:mime});const chunks=[];const status=document.getElementById('aamRecordingStatus');window.aamVoiceRecorder=recorder;let remaining=60;if(status){status.textContent='● Recording · 60s';status.classList.add('recording');}window.aamVoiceCountdown=setInterval(()=>{remaining=Math.max(0,remaining-1);if(status)status.textContent='● Recording · '+remaining+'s';},1000);recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onstop=async()=>{clearTimeout(window.aamVoiceTimer);clearInterval(window.aamVoiceCountdown);stream.getTracks().forEach(t=>t.stop());if(status){status.textContent='Sending voice note…';status.classList.remove('recording');}try{const blob=new Blob(chunks,{type:mime});const signed=await api('/.netlify/functions/social-chat','POST',{action:'sign_voice_upload',mime_type:mime});const uploaded=await socialDb.storage.from('aam-social-voice').uploadToSignedUrl(signed.path,signed.token,blob,{contentType:mime,upsert:false});if(uploaded.error)throw uploaded.error;await api('/.netlify/functions/social-chat','POST',{action:'send',conversation_id:id,message_type:'voice',body:'Voice note (up to 60 seconds)',media_path:signed.path});openChat(id);}catch(e){notice(e.message);if(status)status.textContent=e.message;}};recorder.start();window.aamVoiceTimer=setTimeout(()=>{if(recorder.state==='recording')recorder.stop();},60000);}catch(e){notice(e.message);}}
async function copySocialText(value){try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(String(value));notice('Copied.');return;}const t=document.createElement('textarea');t.value=String(value);t.style.position='fixed';t.style.opacity='0';document.body.appendChild(t);t.select();document.execCommand('copy');t.remove();notice('Copied.');}catch(e){notice('Could not copy this item.');}}
async function copyProfileId(){const id=document.getElementById('aamProfileId')?.value||'';if(id)await copySocialText(id);}
async function copyProfileLink(){const url=document.getElementById('aamProfileUrl')?.value||'';if(url)await copySocialText(url);}
async function shareProfile(){const url=document.getElementById('aamProfileUrl')?.value||'';if(!url)return notice('Profile link is unavailable.');try{if(navigator.share)await navigator.share({title:'All Ads Manager profile',url});else await copySocialText(url);}catch(e){if(e.name!=='AbortError')await copySocialText(url);}}
async function sharePostLink(id){const url=window.location.origin+'/?post='+encodeURIComponent(id);try{if(navigator.share)await navigator.share({title:'All Ads Manager post',url});else await copySocialText(url);}catch(e){if(e.name!=='AbortError')await copySocialText(url);}}
async function sharePost(postId){try{const d=await api('/.netlify/functions/social-chat'),list=d.conversations||[];if(!list.length)return notice('Start a chat with a friend before sharing a post.');const choices=list.map((c,i)=>(i+1)+'. '+(c.other?.display_name||'Friend')).join('\n');const pick=Number(prompt('Share this post with which chat?\n'+choices));if(!Number.isInteger(pick)||pick<1||pick>list.length)return;const conversation=list[pick-1];await api('/.netlify/functions/social-chat','POST',{action:'send',conversation_id:conversation.id,message_type:'shared_post',shared_post_id:postId,body:''});notice('Post shared.');openChat(conversation.id);}catch(e){notice(e.message);}}
async function viewSharedPost(postId){try{const d=await api('/.netlify/functions/social-feed'),p=(d.posts||[]).find(x=>x.id===postId);if(!p)return notice('This shared post is no longer available in the current feed.');mount('<div class="aam-social-card"><button class="aam-social-btn secondary" onclick="AAMSocial.open(&quot;chat&quot;)">← Chats</button><h2>Shared post</h2>'+postCard(p)+'</div>','chat');}catch(e){notice(e.message);}}
async function sendChatMedia(id){const file=document.getElementById('aamChatMedia')?.files?.[0];if(!file)return notice('Choose a picture or video first.');try{const signed=await api('/.netlify/functions/social-chat','POST',{action:'sign_media_upload',mime_type:file.type});const uploaded=await socialDb.storage.from('aam-social-media').uploadToSignedUrl(signed.path,signed.token,file,{contentType:file.type,upsert:false});if(uploaded.error)throw uploaded.error;await api('/.netlify/functions/social-chat','POST',{action:'send',conversation_id:id,message_type:signed.message_type,media_path:signed.path,body:''});openChat(id);}catch(e){notice(e.message);}}
async function sendChat(id){const field=document.getElementById('aamChatBody');try{await api('/.netlify/functions/social-chat','POST',{action:'send',conversation_id:id,body:field?.value||'',message_type:'text'});openChat(id);}catch(e){notice(e.message);}}

const adminToken=()=>sessionStorage.getItem('btAdminToken');
const adminApi=async(method='GET',body)=>{const url='/.netlify/functions/social-admin'+(method==='GET'?'?token='+encodeURIComponent(adminToken()):'');const r=await fetch(url,{method,headers:{'Content-Type':'application/json'},body:method==='GET'?undefined:JSON.stringify({...body,token:adminToken()})});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Administrator social action failed.');return d;};

async function openAdminPromotions(){try{const r=await fetch('/.netlify/functions/social-promotion-admin?token='+encodeURIComponent(adminToken()));const d=await r.json();if(!r.ok)throw new Error(d.error||'Could not load promotions.');const cards=(d.promotions||[]).map(p=>'<article class="aam-social-card"><div class="aam-social-muted">PROMOTION · '+esc(p.status.replaceAll('_',' '))+'</div><h3>'+esc(p.title)+'</h3><p>Customer: <strong>'+esc(p.customer_name)+'</strong></p><img class="aam-social-preview" src="'+esc(p.media_url)+'" alt="Customer advert"><p>'+esc(p.description)+'</p><p>Type: '+esc(p.promotion_type)+' · Requested: '+Number(p.requested_days)+' days</p><p>Provider status: '+esc(p.provider_status.replaceAll('_',' '))+'</p>'+(p.status==='pending_review'?'<label>Price in Money Coins</label><input class="aam-social-field" type="number" min="1" id="aamPromoPrice_'+p.id+'" placeholder="Set price after provider is connected"><label>Admin note</label><input class="aam-social-field" id="aamPromoNote_'+p.id+'" maxlength="500" placeholder="Review note"><button class="aam-social-btn" '+(p.provider_status==='ready'?'':'disabled')+' onclick="AAMSocial.adminPromotionPrice(\''+p.id+'\')">Approve and set price</button><button class="aam-social-btn secondary" onclick="AAMSocial.adminPromotionReject(\''+p.id+'\')">Reject advert</button>' : (p.price_coins?'<p>Price: '+Number(p.price_coins).toLocaleString()+' Money Coins</p>':'')+(p.admin_note?'<p>Note: '+esc(p.admin_note)+'</p>':''))+'</article>').join('');mount('<div class="aam-social-card"><button class="aam-social-btn secondary" onclick="AAMSocial.admin()">← Admin dashboard</button><h2>Manager Promotion review</h2><p class="aam-social-muted">Provider connection: not verified. Pricing and payment remain disabled until the provider is genuinely connected.</p></div>'+(cards||'<div class="aam-social-card">No promotion submissions yet.</div>'),'profile');}catch(e){notice(e.message);}}
async function adminPromotionPrice(id){const price=Number(document.getElementById('aamPromoPrice_'+id)?.value),note=document.getElementById('aamPromoNote_'+id)?.value||'';if(!Number.isSafeInteger(price)||price<1)return notice('Enter a valid Money Coin price.');try{const r=await fetch('/.netlify/functions/social-promotion-admin',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:adminToken(),action:'set_price',promotion_id:id,price_coins:price,admin_note:note})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Could not approve promotion.');notice('Price saved.');openAdminPromotions();}catch(e){notice(e.message);}}
async function adminPromotionReject(id){const note=prompt('Reason for rejecting this advert:');if(note===null)return;try{const r=await fetch('/.netlify/functions/social-promotion-admin',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:adminToken(),action:'reject',promotion_id:id,admin_note:note})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Could not reject promotion.');notice('Advert rejected.');openAdminPromotions();}catch(e){notice(e.message);}}
